for rec in records.sudo():
    employee = rec.x_employee_id.sudo() if rec.x_employee_id else False

    form_code = rec.x_reference_code or 'MCEP-HR-F-0020'
    form_title = 'Clearance Request'
    employee_name = employee.name or employee.display_name or 'Employee'

    vals = {}

    if not rec.x_state:
        vals['x_state'] = 'draft'

    if not rec.x_reference_code:
        vals['x_reference_code'] = form_code

    if not rec.x_responsible_user_id:
        vals['x_responsible_user_id'] = env.user.id

    if employee:
        joining_date = get_joining_date(employee)
        if joining_date and not rec.x_date_of_joining:
            vals['x_date_of_joining'] = joining_date

    if employee and employee.parent_id and not rec.x_assigned_department_responsible_employee_id:
        vals['x_assigned_department_responsible_employee_id'] = employee.parent_id.id

    if employee and 'hr_responsible_id' in employee._fields and employee.hr_responsible_id and not rec.x_hr_user_id:
        vals['x_hr_user_id'] = employee.hr_responsible_id.id

    if rec.x_reason_for_termination != 'other' and rec.x_other_reason_description:
        vals['x_other_reason_description'] = False

    if not rec.x_document_reference:
        emp_part = employee.id if employee else 0
        vals['x_document_reference'] = '%s-%05d-%05d' % (form_code, emp_part, rec.id)
    elif '-EMP-' in rec.x_document_reference:
        vals['x_document_reference'] = rec.x_document_reference.replace('-EMP-', '-', 1)

    document_reference = vals.get('x_document_reference') or rec.x_document_reference or ''
    normalized_name = '%s - %s - %s' % (employee_name, form_title, document_reference or rec.id)

    if rec.x_name != normalized_name:
        vals['x_name'] = normalized_name

    if vals:
        rec.write(vals)

    rec = rec.sudo().browse(rec.id)
    seed_lines(rec)

action = False
clearance_model = env['x_hr.employee_clearance_request'].sudo()


def toast(title, message, kind='warning', sticky=False):
    return {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {
            'title': title,
            'message': message,
            'type': kind,
            'sticky': sticky,
        }
    }


employee = records[:1].sudo() if records else False
if not employee:
    active_id = env.context.get('active_id') or env.context.get('default_x_employee_id')
    employee = env['hr.employee'].sudo().browse(active_id) if active_id else False

if not employee or not employee.exists():
    action = toast('New Clearance Request', 'Open this action from an employee record so the clearance request can be linked and seeded correctly.', 'warning', True)
else:
    clearance = clearance_model.create({
        'x_employee_id': employee.id,
        'x_state': 'draft',
        'x_responsible_user_id': env.user.id,
        'x_assigned_department_responsible_employee_id': employee.parent_id.id if employee.parent_id else False,
        'x_hr_user_id': employee.hr_responsible_id.id if 'hr_responsible_id' in employee._fields and employee.hr_responsible_id else False,
    })

    clearance = clearance_model.browse(clearance.id)

    view = env.ref('hr_employment_custom.view_employee_clearance_request_form', raise_if_not_found=False)

    action = {
        'type': 'ir.actions.act_window',
        'name': clearance.x_name or 'New Clearance Request',
        'res_model': 'x_hr.employee_clearance_request',
        'res_id': clearance.id,
        'view_mode': 'form',
        'target': 'new',
        'context': {
            'default_x_employee_id': employee.id,
        },
    }
    if view:
        action['views'] = [(view.id, 'form')]
